with remaining_keys as (select supplier_id, category from products except all select supplier_id, category from products where category = 'Electronics'), kept_rows as (select s.* from products s join remaining_keys k on s.supplier_id = k.supplier_id and s.category = k.category) select s.id, s.category, s.price, s.cost, s.stock_qty, s.launch_date, s.supplier_id, case when category rlike '^(Fashion|Sports)$' then 'GROUP_B' when category rlike '^(Electronics|Home)$' then 'CORE' else 'EXTENDED' end as category_zone, (select avg(t2.cost) from products t2 where t2.supplier_id = s.supplier_id) as avg_product_cost from kept_rows s order by id, category;
